// === Tab: mySketch ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

let r;
let points = [];
let seed = Math.random() * 1000;

function setup() {
	randomSeed(seed);
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	// pixelDensity(5);
	background(0, 0, 95, 100);

	r = 15;
	x_length = int(width / r);
	y_length = int(height / (r * cos(PI / 6)));
	for (var x = 0; x < x_length + 4; x++) {
		points[x] = [];
		for (var y = 0; y < y_length + 4; y++) {
			//points[x][y] = set(x,y);
			if (y % 2 == 0) {
				points[x][y] = createVector(
					x * r + (width - x_length * r) / 2,
					y * r + (height - r * y_length) / 2
				);
			} else if (y % 2 == 1) {
				points[x][y] = createVector(
					x * r + (width - x_length * r) / 2 + r / 2,
					y * r + (height - r * y_length) / 2
				);
			}
		}
	}
}

function draw() {
	randomSeed(seed);
	noFill();
	strokeCap(SQUARE);
	//strokeWeight(1);
	translate(-r, -r);
	for (var x = 0; x < x_length; x++) {
		for (var y = 0; y < y_length; y++) {
			if (x % 2 == 0 && y % 2 == 0) {
				stroke(10, 90, 95, 95);
				strokeWeight(random(0.5));
				line(
					points[x + 1][y + 4].x,
					points[x + 1][y + 4].y,
					points[x + 2][y + 3].x,
					points[x + 2][y + 3].y
				);
				strokeWeight(random(5));
				line(
					points[x + 2][y + 1].x,
					points[x + 2][y + 1].y,
					points[x + 2][y + 3].x,
					points[x + 2][y + 3].y
				);
				strokeWeight(random(4));
				line(
					points[x + 3][y + 4].x,
					points[x + 3][y + 4].y,
					points[x + 1][y + 3].x,
					points[x + 1][y + 3].y
				);
				stroke(110, 90, 65, 95);
				strokeWeight(random(2));
				line(
					points[x + 1][y + 1].x,
					points[x + 1][y + 1].y,
					points[x + 1][y + 3].x,
					points[x + 1][y + 3].y
				);
				strokeWeight(random(0.2));
				line(
					points[x][y + 3].x,
					points[x][y + 3].y,
					points[x + 2][y + 2].x,
					points[x + 2][y + 2].y
				);
				strokeWeight(random(5));
				line(
					points[x + 3][y + 3].x,
					points[x + 3][y + 3].y,
					points[x + 2][y + 2].x,
					points[x + 2][y + 2].y
				);
			}
		}
	}
	//noLoop();
}

function mouseClicked() {
	seed = Math.random() * 1000;
	randomSeed(seed);
	background(0, 0, 95, 100);
	loop();
}

